'use strict';

// MODULES //

var ABS_MASK = require( '@stdlib/constants/float64/high-word-abs-mask' );
var HIGH_SIGNIFICAND_MASK = require( '@stdlib/constants/float64/high-word-significand-mask' );
var toWord = require( '@stdlib/number/float32/base/to-word' );
var fromWord = require( '@stdlib/number/float32/base/from-word' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var BIAS = require( '@stdlib/constants/float32/exponent-bias' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var kernelLog1p = require( '@stdlib/math/base/special/kernel-log1p' );


// VARIABLES //

var TWO25 =  3.3554432000e+07;     // 0x4c000000
var IVLN10HI = 4.3432617188e-01;  // 0x3ede6000
var IVLN10LO = -3.1689971365e-05;  // 0xb804ead9
var LOG10_2HI = 3.0102920532e-01; // 0x3e9a2080
var LOG10_2LO = 7.9034151668e-07; // 0x355427db

// 0x7f800000 = 2146435072 => 0 11111111111 00000000000000000000 => biased exponent: 2047 = 1023+1023 => 2^1023
var HIGH_MAX_NORMAL_EXP = 0x7f800000|0; // asm type annotation

// 0x00800000 = 1048576 => 0 00000000001 00000000000000000000 => biased exponent: 1 = -1022+1023 => 2^-1022
var HIGH_MIN_NORMAL_EXP = 0x00800000|0; // asm type annotation

// 0x3f800000 = 1072693248 => 0 01111111111 00000000000000000000 => biased exponent: 1023 = 0+1023 => 2^0 = 1
var HIGH_BIASED_EXP_0 = 0x3f800000|0; // asm type annotation


// MAIN //

/**
* Evaluates the common logarithm (base ten) for single-precision floating-point number.
*
* @param {NonNegativeNumber} x - input value
* @returns {number} function value
*
* @example
* var v = log10f( 4.0 );
* // returns ~0.602
*
* @example
* var v = log10f( 8.0 );
* // returns ~0.903
*
* @example
* var v = log10f( 0.0 );
* // returns -Infinity
*
* @example
* var v = log10f( Infinity );
* // returns Infinity
*
* @example
* var v = log10f( NaN );
* // returns NaN
*
* @example
* var v = log10f( -4.0 );
* // returns NaN
*/
function log10f( x ) {
	var hfsq;
	var hi;
	var lo;
	var hx;
	var f;
	var R;
	var y;
	var i;
	var k;

	if ( isnan( x ) || x < 0.0 ) {
		return NaN;
	}
	x =float64ToFloat32( x );
	k = 0|0; // asm type annotation

	if ( hx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-1022
		if ( ( ( hx & ABS_MASK ) | lx ) === 0 ) {
			return NINF;
		}
		k -= 25|0; // asm type annotation

		// Subnormal number, scale up x:
		x *= TWO25;
		hx = toWord( x );
	}
	if ( hx >= HIGH_MAX_NORMAL_EXP ) {
		return x + x;
	}
	// Case: log(1) = +0
	if ( hx === HIGH_BIASED_EXP_0 ) {
		return 0.0;
	}
	k += ( ( hx >> 23 ) - BIAS )|0; // asm type annotation
	hx &= HIGH_SIGNIFICAND_MASK;
	i = ( hx + ( 0x4afb0d ) & HIGH_MIN_NORMAL_EXP )|0; // asm type annotation

	// Normalize `x` or `x/2`...
	x = fromWord( hx | ( i ^ HIGH_BIASED_EXP_0 ) );
	k += ( i >> 23 )|0; // asm type annotation
	y = k;
	f = x - 1.0;
	hfsq = 0.5 * f * f;
	R = kernelLog1p( f );

	// See e_log2f.c and e_log2.c for details.
	hi = f - hfsq;
	hx = toWord( hi );
	hi = fromWord( hx&ABS_MASK);
	lo = ( f - hi ) - hfsq + R;
	return ( y * LOG10_2LO ) + ( ( lo + hi ) * IVLN10LO ) + ( lo * IVLN10HI ) + ( hi * IVLN10HI ) + ( y * LOG10_2HI );
}


// EXPORTS //

module.exports = log10f;
